import { Routes, Route } from "react-router-dom";
import DashboardLayout from "../layouts/DashboardLayout";
import LeadDashboard from "../features/leads/LeadDashboard";
import LeadForm from "../features/leads/LeadForm";
import LeadEdit from "../features/leads/LeadEdit";

import ProtectedRoute from "./ProtectedRoute";
import Login from "../features/staff/Login";
import Staff from "../features/staff/Staff";
import AddStaff from "../features/staff/AddStaff";
import Work from "../features/staff/Work";
import ContactListForm from "../features/contactList/ContactListForm";
import ContactListReport from "../features/contactList/ContactListReport";
import ContactListReportOverview from "../features/contactList/ContactListReportOverview";
import AddCall from "../features/contactList/AddCall";
import SummaryReport from "../features/contactList/SummaryReport";
import InvalidNumbers from "../features/contactList/InvalidNumbers";
import RemindersReport from "../features/contactList/RemindersReport";
import SurvayReport from "../features/survay/SurvayReport";
import OrderValuationReport from "../features/orderValuation/orderValuationReport";
import BillView from "../features/bill/BillView";
import IncomeReport from "../features/accounts/income/IncomeReport";
import TelecallerReport from "../features/staff/workStatus/TelecallerReport";
import InterestedList from "../features/contactList/InterestedList";
import Settings from "../features/settings/Settings";
import SurvayorReport from "../features/staff/workStatus/SurvayorReport";
import RecordsReport from "../features/contactList/RecordsReport";
import CustomerHistory from "../features/contactList/CustomerHistory";
import TaxManage from "../features/orderValuation/TaxManage";
import OrderValuationForm from "../features/orderValuation/OrderValuationForm";

import AkarniProjects from "../features/projects/AkarniProject";
import Akarni from "../features/projects/Akarni";

import IndexReport from "../features/survay/IndexReport";
import FinalProjects from "../features/projects/FinalProjects";
import DailyWordReport from "../features/staff/survayor/DailyWordReport";
import SurvayorExpense from "../features/staff/survayor/SurvayorExpense";
import CurrentProjects from "../features/projects/CurrentProjects";
import { useAuth } from "../config/AuthContext";
import AnalyticsReport from "../features/survay/AnalysisReport";
import TaxRegister from "../features/survay/TaxRegister";
import TarijReport from "../features/survay/TarijReport";
import SurvayFormImage from "../features/survay/SurvayFormImage";
import SurvayReportImage2 from "../features/survay/SurvayReportImage2";
import AkarniExcelEdit from "../components/excel/AkarniExcelEdit";
import BillWork from "../features/staff/BillWork";
import NotFound from "../components/NotFound";
import BillerReport from "../features/staff/workStatus/BillerReport";
import SurvayInsertForm from "../components/SurveyInsertForm";
import ManageCertificate from "../features/meetings/ManageCertificate";
import ArjiLetter from "../features/meetings/ArjiLetter";
import Certificate from "../features/meetings/Certificate";
import TharavSet from "../features/orderValuation/TharavSet";
import CancledProjects from "../features/projects/CancledProjects";
import UpdateStatus from "../features/projects/Status";
import OwnerAdmin from "../layouts/OwnerAdmin";
import ManglaRegister from "../features/survay/ManglaReport";
import VasulatRegister from "../features/survay/VasulatReport";
import TaxEntryFrom from "../components/excel/TaxEntryFrom";
import TaxEntry from "../features/survay/TaxEntry";
import KachaReport from "../features/survay/KachaReport";
import SendTempMessage from "../features/contactList/SendTempMessage";
import AddService from "../features/services/AddService";
import AddAkarni from "../features/projects/AddAkarni";
import ManageAkarni from "../features/projects/ManageAkarni";
import ManageService from "../features/services/ManageService";
import AddCustomer from "../features/contactList/AddCustomer";
import ListApplication from "../features/meetings/ListApplication";
import BulkRecords from "../features/contactList/BulkRecords";
import ManageCertificate2 from "../features/meetings/ManageCertificate2";
import ArjiLetter2 from "../features/meetings/ArjiLetter2";
import ManageStatus from "../features/projects/ManageStatus";
import Analytics from "../features/contactList/Analytics";
import DataEntryProjects from "../features/projects/DataEntryProjects";

import SurvayReport2 from "../features/dataentry/SurvayReport";
import TaxRegister2 from "../features/dataentry/TaxRegister";

import BillViewDE from "../features/bill/BillDE";
import DataEntry from "../features/projects/DataEntry";
import IncomeCategories from "../features/accounts/income/IncomeCategories";
import IndexReport2 from "../features/dataentry/IndexReport";
import TarijReport2 from "../features/dataentry/TarijReport";
import SurveyBulkUpload from "../features/survay/SurveyBulkUpload";
import WaterTaxRegister2 from "../features/dataentry/WaterTaxRegister";
import WaterTaxRegister from "../features/survay/WaterTaxRegister";

export default function AppRoutes() {
  const { user } = useAuth();

  return (
    <Routes>
      <Route
        path="/"
        element={
          <ProtectedRoute
            allowedRoles={[
              "owner",
              "accountant",
              "operator",
              "surveyor",
              "telecaller",
              "monitor",
            ]}
          >
            <DashboardLayout />
          </ProtectedRoute>
        }
      >
        <Route
          index
          element={
            <>
              {user?.role === "owner" ? (
                <OwnerAdmin />
              ) : user?.role === "telecaller" ? (
                <ContactListForm />
              ) : (
                <></>
              )}
            </>
          }
        />
        <Route path="/leads/report" element={<LeadDashboard />} />
        <Route path="/leads/form" element={<LeadForm />} />
        <Route path="/leads/edit/:id" element={<LeadEdit />} />

        <Route path="/customers/form" element={<ContactListForm />} />
        <Route path="/customers/add" element={<AddCustomer />} />
        <Route path="/customers/bulk" element={<BulkRecords />} />
        <Route path="/customers/form/:id" element={<ContactListForm />} />

        <Route path="/customers/add-call/:id" element={<AddCall />} />
        <Route
          path="/customers/overview"
          element={<ContactListReportOverview />}
        />
        <Route path="/customers/report" element={<ContactListReport />} />

        <Route path="/customers/analytics" element={<Analytics />} />

        <Route path="/customers/summary" element={<SummaryReport />} />
        <Route path="/customers/invalids" element={<InvalidNumbers />} />
        <Route path="/customers/reminders" element={<RemindersReport />} />

        <Route
          path="/customers/history/:id"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <CustomerHistory />
            </ProtectedRoute>
          }
        />

        <Route
          path="/customers/interested"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <InterestedList />
            </ProtectedRoute>
          }
        />

        <Route
          path="/customers/total"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <RecordsReport />
            </ProtectedRoute>
          }
        />

        <Route path="/dataentry">
          <Route index element={<DataEntryProjects />} />

          <Route path="manage/:projectId" element={<DataEntry />} />

          <Route
            path="akarniReport/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <SurvayReport2 />
              </ProtectedRoute>
            }
          />

          {/* <Route
            path="insert/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <SurvayInsertForm />
              </ProtectedRoute>
            }
          /> */}

          <Route
            path="indexReport/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <IndexReport2 />
              </ProtectedRoute>
            }
          />

          <Route
            path="taxRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxRegister2 />
              </ProtectedRoute>
            }
          />

          <Route
            path="waterTaxRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <WaterTaxRegister2 />
              </ProtectedRoute>
            }
          />

          {/* <Route
            path="taxform/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxEntry />
              </ProtectedRoute>
            }
          /> */}

          {/* <Route
            path="taxform/:projectId/:mId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxEntryFrom />
              </ProtectedRoute>
            }
          /> */}

          <Route
            path="tarij/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TarijReport2 />
              </ProtectedRoute>
            }
          />

          <Route
            path="bill/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <BillViewDE />
              </ProtectedRoute>
            }
          />
        </Route>

        <Route path="/survay">
          <Route index element={<AkarniProjects />} />

          <Route path="manage/:projectId" element={<Akarni />} />

          <Route path="bulk/:projectId" element={<SurveyBulkUpload />} />

          <Route
            path="akarniReport/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <SurvayReport />
              </ProtectedRoute>
            }
          />

          <Route
            path="insert/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <SurvayInsertForm />
              </ProtectedRoute>
            }
          />

          <Route
            path="akarniImgReport/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <SurvayReportImage2 />
              </ProtectedRoute>
            }
          />

          <Route
            path="indexReport/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <IndexReport />
              </ProtectedRoute>
            }
          />

          <Route
            path="taxRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxRegister />
              </ProtectedRoute>
            }
          />

          <Route
            path="waterTaxRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <WaterTaxRegister />
              </ProtectedRoute>
            }
          />

          <Route
            path="taxform/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxEntry />
              </ProtectedRoute>
            }
          />

          <Route
            path="taxform/:projectId/:mId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TaxEntryFrom />
              </ProtectedRoute>
            }
          />

          <Route
            path="manglaRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <ManglaRegister />
              </ProtectedRoute>
            }
          />

          <Route
            path="vasulatRegister/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <VasulatRegister />
              </ProtectedRoute>
            }
          />

          <Route
            path="tarij/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <TarijReport />
              </ProtectedRoute>
            }
          />

          <Route
            path="analysis/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <AnalyticsReport />
              </ProtectedRoute>
            }
          />

          <Route
            path="kacha/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <KachaReport />
              </ProtectedRoute>
            }
          />

          <Route
            path="bill/:projectId"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <BillView />
              </ProtectedRoute>
            }
          />

          <Route path="dailyReport" element={<DailyWordReport />} />
          <Route path="expenseReport" element={<SurvayorExpense />} />
        </Route>

        <Route path="/whatsapp">
          <Route path="temp" element={<SendTempMessage />} />
        </Route>

        {/* Order Valuation Routes Start */}
        <Route path="/orderValuation">
          <Route path="form/:projectId" element={<OrderValuationForm />} />
          <Route path="tax/:projectId" element={<TaxManage />} />

          <Route path="report/:projectId" element={<OrderValuationReport />} />
          <Route path="tharav/:projectId" element={<TharavSet />} />
        </Route>
        {/* Order Valuation Routes End */}

        {/* Meeting Routes Start */}
        <Route path="meeting">
          <Route path="manage" element={<ManageCertificate />} />
          <Route path="arji/:id" element={<ArjiLetter />} />
          <Route path="certificate/:id" element={<Certificate />} />
        </Route>
        {/* Meeting Routes End */}

        <Route path="yaadi">
          <Route path="manage" element={<ManageCertificate2 />} />
          <Route path="arji/:id" element={<ArjiLetter2 />} />
          <Route path="list/:id" element={<ListApplication />} />
        </Route>

        {/* Accounts Routes Start */}
        <Route path="accounts">
          <Route path="income" element={<IncomeReport />} />
          <Route path="income-category" element={<IncomeCategories />} />
          {/* <Route path="expense" element={<ExpenseReport />} /> */}
        </Route>
        {/* Accounts Routes End */}

        <Route path="/services">
          <Route path="new" element={<AddService />} />
          <Route path="add">
            <Route path="akarni" element={<AddAkarni />} />
          </Route>

          <Route path="manage">
            <Route index element={<ManageService />} />
            <Route path="akarni" element={<ManageAkarni />} />
          </Route>
        </Route>

        {/* Projects Routes Start */}
        <Route path="projects">
          {/* <Route path="add" element={<AddProject />} /> */}
          <Route
            path="first"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <AkarniProjects />
              </ProtectedRoute>
            }
          />

          <Route
            path="current"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <CurrentProjects />
              </ProtectedRoute>
            }
          />

          <Route
            path="final"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <FinalProjects />
              </ProtectedRoute>
            }
          />

          <Route
            path="cancled"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <CancledProjects />
              </ProtectedRoute>
            }
          />

          <Route
            path="update"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <ManageStatus />
              </ProtectedRoute>
            }
          />

          <Route
            path="update/:id"
            element={
              <ProtectedRoute allowedRoles={["owner"]}>
                <UpdateStatus />
              </ProtectedRoute>
            }
          />
        </Route>
        {/* Projects Routes End */}

        {/* Staff Routes Start */}
        <Route
          path="/staff/manage"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <Staff />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/add"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <AddStaff />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/edit/:id"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <AddStaff />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/work"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <Work />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/billwork"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <BillWork />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/telecallerReport"
          element={
            <ProtectedRoute allowedRoles={["owner", "monitor"]}>
              <TelecallerReport />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/survayorReport"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <SurvayorReport />
            </ProtectedRoute>
          }
        />

        <Route
          path="/staff/billerReport"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <BillerReport />
            </ProtectedRoute>
          }
        />

        <Route
          path="/settings"
          element={
            <ProtectedRoute allowedRoles={["owner"]}>
              <Settings />
            </ProtectedRoute>
          }
        />

        <Route path="/excel">
          <Route path="akarni/:projectId" element={<AkarniExcelEdit />} />
        </Route>
      </Route>
      {/* Staff Routes End */}

      <Route path="/login" element={<Login />} />

      <Route path="*" element={<NotFound />} />
    </Routes>
  );
}
